CREATE OR REPLACE FUNCTION public.sync_event_title()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
    if new.title is null or new.title = '' then
        new.title := new.name;
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.foreman_add_subcontractor(p_project_id uuid, p_name text, p_comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF NOT public.is_foreman() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF p_project_id IS NULL OR NULLIF(trim(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Project and subcontractor name are required';
  END IF;

  INSERT INTO public.subcontractors(project_id, name, comment, planned_amount, has_vat)
  VALUES (p_project_id, trim(p_name), p_comment, 0, false)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_payable_paid_amount_from_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if tg_op='DELETE' then
   if old.article='Погашение кредиторки' then perform public.recalc_payable_paid_amount(old.payable_id); end if;
   return old;
 elsif tg_op='UPDATE' then
   if old.article='Погашение кредиторки' then perform public.recalc_payable_paid_amount(old.payable_id); end if;
   if new.article='Погашение кредиторки' then perform public.recalc_payable_paid_amount(new.payable_id); end if;
   return new;
 else
   if new.article='Погашение кредиторки' then perform public.recalc_payable_paid_amount(new.payable_id); end if;
   return new;
 end if;
end $function$
